#[test]
fn human_facing_kinds_carry_the_human_overlay() {
    let human = [
        (EventKind::IntentCreated, Some(Lane::Plan)),
        (EventKind::IntentAmended, Some(Lane::Plan)),
        (EventKind::IntentAnswered, Some(Lane::Plan)),
        (EventKind::QuestionAsked, Some(Lane::Plan)),
        (EventKind::QuestionAnswered, Some(Lane::Plan)),
        (EventKind::ApprovalRequested, Some(Lane::Plan)),
        (EventKind::ApprovalGiven, Some(Lane::Plan)),
        (EventKind::MissionPaused, Some(Lane::Plan)),
        (EventKind::MissionResumed, Some(Lane::Plan)),
        (EventKind::ReviewOutcome, Some(Lane::Gate)),
        (EventKind::PermissionRequested, None),
        (EventKind::PermissionGranted, None),
        (EventKind::PermissionDenied, None),
    ];
    for (kind, fixed) in &human {
        assert_eq!(kind.overlay(), Some(Overlay::Human), "{kind:?}");
        match fixed {
            Some(lane) => assert_eq!(kind.lane(Role::Worker), *lane, "{kind:?}"),
            None => {
                // `permission.*` lands in the phase of the session that asks.
                assert_eq!(kind.lane(Role::Worker), Lane::Build);
                assert_eq!(kind.lane(Role::ScrutinyValidator), Lane::Scrutiny);
