    let carrying: Vec<&EventKind> = human.iter().map(|(kind, _)| kind).collect();
    for kind in EventKind::KNOWN {
        if !carrying.contains(&kind) {
            assert_eq!(kind.overlay(), None, "{kind:?}");
        }
    }
    assert_eq!(
        EventKind::Unknown {
            raw_type: "x".to_owned()
        }
        .overlay(),
        None
    );
}

